// Latin-1 subsets of Liberation Sans 2.1.5, renamed QCDS Report Sans.
// Font software: SIL OFL 1.1; see report-fonts-LICENSE.txt.
const regular = "";
const bold = "";
export function registerReportFonts(doc) {
  doc.addFileToVFS("QCDSReportSans-Regular.ttf", regular);
  doc.addFont("QCDSReportSans-Regular.ttf", "QCDSReport", "normal");
  doc.addFileToVFS("QCDSReportSans-Bold.ttf", bold);
  doc.addFont("QCDSReportSans-Bold.ttf", "QCDSReport", "bold");
}
